using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;
[InitializeOnLoad]public static class RoundDockRopes{static RoundDockRopes(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("RoundDockRopes.request"))return;File.Delete("RoundDockRopes.request");Run();}
static void Run(){try{int added=0;for(int index=1;index<=6;index++){string path="Assets/Scenes/Oasis/SouthBeach/Docking Pier "+index+".prefab";var prefab=PrefabUtility.LoadPrefabContents(path);var f=prefab.GetComponentsInChildren<MeshFilter>().Single(v=>v.name=="Shared atlas dock details");var mesh=f.sharedMesh;var oldp=mesh.vertices;var oldn=mesh.normals;var oldu=mesh.uv;var oldc=mesh.colors;var oldw=new List<Vector4>();mesh.GetUVs(1,oldw);var oldids=mesh.triangles;var p=new List<Vector3>();var n=new List<Vector3>();var uv=new List<Vector2>();var c=new List<Color>();var w=new List<Vector4>();var ids=new List<int>();for(int i=0;i<oldids.Length;i+=3)if(oldw[oldids[i]].x!=3){int first=p.Count;for(int j=0;j<3;j++){int id=oldids[i+j];p.Add(oldp[id]);n.Add(oldn[id]);uv.Add(oldu[id]);c.Add(oldc[id]);w.Add(oldw[id]);}ids.AddRange(new[]{first,first+1,first+2});}
float span=52+((index-1)%3)*7;foreach(float x in new[]{-2.15f,2.15f})foreach(float y in new[]{.75f,1.18f}){float arc=0;for(float z=4;z+7<span-6;z+=7){int first=p.Count;Vector3 previous=Vector3.zero;int rings=7,sides=8;for(int ring=0;ring<rings;ring++){float t=ring/(float)(rings-1);var center=new Vector3(x,y-.12f*Mathf.Sin(t*Mathf.PI),z+7*t);var axis=new Vector3(0,-.12f*Mathf.PI*Mathf.Cos(t*Mathf.PI)/7,1).normalized;var right=Vector3.right;var side=Vector3.Cross(axis,right).normalized;if(ring>0)arc+=Vector3.Distance(center,previous);previous=center;for(int k=0;k<=sides;k++){float a=k*Mathf.PI*2/sides;var radial=right*Mathf.Cos(a)+side*Mathf.Sin(a);p.Add(center+radial*.035f);n.Add(radial);uv.Add(new Vector2(arc/ .35f,k/(float)sides));c.Add(new Color(.95f,.9f,.77f,1));w.Add(new Vector4(3,0,0,0));}}for(int ring=0;ring<rings-1;ring++)for(int k=0;k<sides;k++){int a=first+ring*(sides+1)+k,b=a+(sides+1);ids.AddRange(new[]{a,a+1,b,a+1,b+1,b});added+=2;}}}
mesh.Clear();mesh.indexFormat=UnityEngine.Rendering.IndexFormat.UInt32;mesh.SetVertices(p);mesh.SetNormals(n);mesh.SetUVs(0,uv);mesh.SetUVs(1,w);mesh.SetColors(c);mesh.SetTriangles(ids,0);mesh.RecalculateBounds();mesh.name="Dock details with round cylindrical UV ropes";EditorUtility.SetDirty(mesh);prefab.GetComponent<LODGroup>().RecalculateBounds();PrefabUtility.SaveAsPrefabAsset(prefab,path);PrefabUtility.UnloadPrefabContents(prefab);}AssetDatabase.SaveAssets();var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);var pier=scene.GetRootGameObjects().Single(g=>g.name=="South Beach Bays and Docking Piers").transform.GetChild(2);var target=pier.TransformPoint(new Vector3(-2.15f,1.03f,20));typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{scene,target+pier.TransformDirection(new Vector3(1.9f,.7f,-2.8f)),target+pier.forward*1.5f,"Round-Rope-Closeup"});File.WriteAllText("FinalEnvironmentRoadReview/RoundDockRopesReport.txt","SUCCESS six docking pier prefabs; smooth eight-sided rope cylinders, seven curved rings per span, circumference UV wrapping and consistent 35cm fibre repeats; rope triangles="+added+"; existing shared atlas/material, other detail geometry and LODs retained.");}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/RoundDockRopesReport.txt","FAILED "+e);Debug.LogException(e);}}}
